import re,unicodedata
P=Path(__file__).parent
items=[('Salons de coiffure','dégâts des eaux, matériel de coiffure, responsabilité envers les clients'),('Instituts de beauté','appareils de soins, responsabilité liée aux prestations, locaux'),('Restaurants','cuisine professionnelle, incendie, perte d’exploitation'),('Boulangeries','fours, marchandises réfrigérées, interruption d’activité'),('Boucheries','chaîne du froid, stocks, responsabilité alimentaire'),('Commerces de proximité','stocks, vitrines, vol et responsabilité civile'),('Fleuristes','marchandises périssables, locaux, livraisons'),('Garages automobiles','véhicules confiés, atelier, responsabilité professionnelle'),('Plombiers','dégâts des eaux, responsabilité décennale selon travaux, outillage'),('Électriciens','installations électriques, responsabilité décennale selon travaux, matériel'),('Maçons','ouvrages, responsabilité décennale, engins'),('Couvreurs','étanchéité, responsabilité décennale, travaux en hauteur'),('Peintres','dommages aux biens confiés, outillage, responsabilité selon travaux'),('Menuisiers','pose, atelier, responsabilité décennale selon travaux'),('Entreprises du bâtiment','chantiers, décennale, responsabilité civile'),('Transporteurs','flotte, marchandises transportées, responsabilité du transporteur'),('Professions libérales','responsabilité professionnelle, locaux, protection juridique'),('Consultants','erreurs de conseil, responsabilité professionnelle, cyberrisques'),('Agences immobilières','responsabilité professionnelle, locaux, garantie financière selon activité'),('TPE et PME','locaux, flotte, santé collective, interruption d’activité'),('Multirisque immeuble','incendie, dégâts des eaux, dommages aux parties communes'),('Copropriété','responsabilité du syndicat, parties communes, dommages au bâtiment'),('Syndic professionnel','immeubles gérés, historique des sinistres, échéances du portefeuille'),('Syndic bénévole','petites copropriétés, responsabilité du syndicat, dommages au bâtiment'),('Immeuble SCI','patrimoine locatif, responsabilité propriétaire, pertes de loyers selon contrat')]
def slug(s): return re.sub('[^a-z0-9]+','-',unicodedata.normalize('NFKD',s.lower()).encode('ascii','ignore').decode()).strip('-')
def page(title,body,desc=''):
 return f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="description" content="{escape(desc,quote=True)}"><title>{escape(title)} | ASSURER MON MÉTIER</title><link rel="stylesheet" href="/style.css"></head><body><header><a class="brand" href="/">ASSURER MON MÉTIER<small>Par BRUMERE ASSURANCES</small></a><nav><a href="/#metiers">Professionnels</a><a href="/#immeubles">Copropriétés</a><a href="/cabinet.html">Notre cabinet</a><a href="tel:+33176310076">01 76 31 00 76</a></nav></header><main>{body}</main><footer><strong>BRUMERE ASSURANCES</strong><p>3 rue Louise de Vilmorin, 91540 Mennecy · 10 avenue de Brétigny, 91700 Sainte-Geneviève-des-Bois</p><p>ORIAS 10052260 · <a href="mailto:cbl@abeille-assurances.com">cbl@abeille-assurances.com</a> · <a href="/legal.html">Informations légales et confidentialité</a></p><p>Version de test — non destinée à la collecte de données réelles.</p></footer></body></html>'''
def cards(rows): return '<div class="grid">'+''.join(f'<a class="tile" href="/assurance-{slug(n)}.html"><h3>{escape(n)}</h3><p>{escape(r)}</p><b>Découvrir →</b></a>' for n,r in rows)+'</div>'
def form(immo=False):
 fields='<label>Nom ou société<input required></label><label>E-mail<input type="email" required></label><label>Téléphone<input type="tel"></label>'
 fields+= '<label>Code postal de l’immeuble<input pattern="[0-9]{5}" required></label><label>Nombre de lots<input type="number" min="1"></label><label>Surface en m²<input type="number" min="1"></label>' if immo else '<label>Activité<input required></label><label>Code postal<input pattern="[0-9]{5}" required></label>'
 return '<section id="devis"><h2>Demander une étude personnalisée</h2><p>Formulaire de démonstration : utilisez uniquement des données fictives. Aucun envoi ni stockage.</p><form onsubmit="event.preventDefault();this.reset();this.querySelector(\'output\').textContent=\'Test terminé : aucune donnée envoyée.\'">'+fields+'<label>Échéance actuelle<input type="date"></label><button>Tester la demande de devis</button><output role="status"></output></form></section>'
for i,(n,r) in enumerate(items):
 title='Assurance '+n
 body=f'<section class="hero"><p>ASSURANCE {"IMMOBILIÈRE" if i>=20 else "PROFESSIONNELLE"}</p><h1>{escape(title)}</h1><p>Une étude adaptée à votre activité et à vos besoins, partout en France.</p><a class="cta" href="#devis">Demander un devis</a></section><section><h2>Quels risques étudier ?</h2><p>Pour votre projet : {escape(r)}.</p><p>Nous étudions votre situation, vos contrats actuels et les garanties pertinentes. Les garanties, exclusions, franchises et conditions dépendent du contrat proposé et de l’acceptation du risque.</p><h2>Préparer votre étude</h2><p>Munissez-vous de votre contrat actuel, de son échéance et de votre historique de sinistres. Contactez notre cabinet au <a href="tel:+33176310076">01 76 31 00 76</a>.</p></section>'+form(i>=20)
 (P/f'assurance-{slug(n)}.html').write_text(page(title,body,title+' : étude personnalisée avec BRUMERE ASSURANCES.'),encoding='utf8')
(P/'index.html').write_text(page('Assurance professionnelle et immeuble','<section class="hero"><p>VOTRE PARTENAIRE ASSURANCE</p><h1>Votre métier, votre entreprise, votre patrimoine. Nous les protégeons.</h1><p>Artisans · Commerçants · Entreprises · Professions libérales · Syndics · Copropriétés</p><a class="cta" href="#metiers">Trouver mon assurance</a> <a class="cta alt" href="tel:+33176310076">01 76 31 00 76</a></section><section id="metiers"><h2>Assurances par métier</h2>'+cards(items[:20])+'</section><section id="immeubles"><h2>Assurance copropriété et immeuble</h2>'+cards(items[20:])+'</section><section><h2>Un cabinet proche de vous</h2><p>Deux agences en Essonne, un accompagnement national et une gestion des sinistres en interne.</p></section>','Assurances professionnelles et immobilières, étude personnalisée partout en France.'),encoding='utf8')
(P/'cabinet.html').write_text(page('Notre cabinet','<section><h1>BRUMERE ASSURANCES</h1><p>Deux agences en Essonne, à Mennecy et Sainte-Geneviève-des-Bois. Proximité, disponibilité et gestion des sinistres en interne.</p><a class="cta" href="tel:+33176310076">Nous appeler</a></section>'),encoding='utf8')
(P/'legal.html').write_text(page('Informations légales','<section><h1>Informations légales et confidentialité</h1><p>Projet de mentions à valider avant publication. Éditeur : BRUMERE ASSURANCES, ORIAS 10052260 (à vérifier). Contact : cbl@abeille-assurances.com.</p><p>À compléter : identité juridique, SIREN, siège, directeur de publication, statut et mandats, réclamations, médiation, hébergeur, informations réglementaires et politique de traitement des données.</p><p>Cette version de test ne transmet ni ne conserve les données des formulaires et ne contient aucun traceur publicitaire.</p></section>'),encoding='utf8')
